    return max(low, min(n, high))


def page_bounds(page, per_page, total):
    if per_page < 1:
        raise ValueError('per_page must be at least 1')
    start = clamp((page - 1) * per_page, 0, total)
    return start, clamp(start + per_page, 0, total)

