def plural(n, word):
    return f"{n} {word}" + ("" if n == 1 else "s")


def human_size(n_bytes):
    if n_bytes < 1000:
        return f'{n_bytes} B'
    value = n_bytes
    for unit in ('kB', 'MB', 'GB'):
        value /= 1000
        if value < 1000 or unit == 'GB':
            return f'{value:.1f} {unit}'

