def _field(v):
    if v is None:
        return ''
    if isinstance(v, bool):
        return 'Y' if v else 'N'
    return str(v).replace('\t', ' ').replace('\r\n', ' ').replace('\n', ' ')


def to_row(values):
    return '\t'.join(_field(v) for v in values)

